def charlie_cipher(s):
    result = []
    n = 0
    for ch in s:
        if ch.isascii() and ch.isalpha():
            n += 1
            base = ord('A') if ch.isupper() else ord('a')
            shifted = (ord(ch) - base + n) % 26
            result.append(chr(base + shifted))
        else:
            result.append(ch)
    return ''.join(result)
